args.command:
curl -s https://cdn.jsdelivr.net/npm/cannon-es@0.20.0/dist/cannon-es.cjs -o /tmp/cannon-es.cjs && node -e "
const CANNON = require('/tmp/cannon-es.cjs');
const world = new CANNON.World();
world.gravity.set(0, -9.81, 0);
world.solver.iterations = 20;

// Ground
const groundBody = new CANNON.Body({ mass: 0 });
groundBody.addShape(new CANNON.Plane());
groundBody.quaternion.setFromAxisAngle(new CANNON.Vec3(1, 0, 0), -Math.PI / 2);
world.addBody(groundBody);

// 12 cols x 8 rows x 2 layers
const bw = 0.5, bh = 0.24, bd = 0.2;
const bricks = [];
for (let r = 0; r < 8; r++) {
  const y = bh / 2 + r * bh;
  for (let c = 0; c < 12; c++) {
    const offsetX = (r % 2 === 1) ? bw * 0.25 : 0;
    const x = (c - 5.5) * bw + offsetX;
    for (let l = 0; l < 2; l++) {
      const z = (l - 0.5) * bd;
      const b = new CANNON.Body({
        mass: 2.5,
        shape: new CANNON.Box(new CANNON.Vec3(bw/2 - 0.002, bh/2 - 0.002, bd/2 - 0.002)),
        position: new CANNON.Vec3(x, y, z)
      });
      world.addBody(b);
      bricks.push(b);
    }
  }
}
console.log('Bricks added:', bricks.length);

for (let i = 0; i < 60; i++) {
  world.step(1/60);
}
let maxDrift = 0;
for (const b of bricks) {
  const v = b.velocity.length();
  if (v > maxDrift) maxDrift = v;
}
console.log('After 1 second of gravity, max brick velocity:', maxDrift.toFixed(4));
"

