const CANNON = require('/tmp/cannon-es.cjs');
const world = new CANNON.World();
world.gravity.set(0, -9.81, 0);
world.solver.iterations = 30;
world.solver.tolerance = 0.0001;

// Ground
const groundMat = new CANNON.Material('ground');
const brickMat = new CANNON.Material('brick');
const cm = new CANNON.ContactMaterial(brickMat, groundMat, { friction: 0.85, restitution: 0.18 });
world.addContactMaterial(cm);
const cmBrick = new CANNON.ContactMaterial(brickMat, brickMat, { friction: 0.72, restitution: 0.18 });
world.addContactMaterial(cmBrick);

const groundBody = new CANNON.Body({ mass: 0, material: groundMat });
groundBody.addShape(new CANNON.Plane());
groundBody.quaternion.setFromAxisAngle(new CANNON.Vec3(1, 0, 0), -Math.PI / 2);
world.addBody(groundBody);

// 12 cols x 8 rows x 2 layers
const bw = 0.5, bh = 0.24, bd = 0.2;
const bricks = [];
for (let r = 0; r < 8; r++) {
  const y = bh / 2 + r * (bh + 0.001);
  for (let c = 0; c < 12; c++) {
    const offsetX = (r % 2 === 1) ? (bw * 0.25) : 0;
    const x = (c - 5.5) * (bw + 0.001) + offsetX;
    for (let l = 0; l < 2; l++) {
      const z = (l - 0.5) * (bd + 0.001);
      const b = new CANNON.Body({
        mass: 2.5,
        material: brickMat,
        shape: new CANNON.Box(new CANNON.Vec3(bw/2 - 0.002, bh/2 - 0.002, bd/2 - 0.002)),
        position: new CANNON.Vec3(x, y, z)
      });
      world.addBody(b);
      bricks.push(b);
    }
  }
}
console.log('Bricks count:', bricks.length);
for (let i = 0; i < 60; i++) {
  world.step(1/60);
}
let maxV = 0;
for (const b of bricks) {
  maxV = Math.max(maxV, b.velocity.length());
}
console.log('Max brick velocity after 1 sec standing:', maxV.toFixed(5));
"

