const CANNON = require('/tmp/cannon-es.cjs');
const world = new CANNON.World();
world.gravity.set(0, -9.81, 0);
world.solver.iterations = 25;

const groundMat = new CANNON.Material('ground');
const brickMat = new CANNON.Material('brick');
const carMat = new CANNON.Material('car');

world.addContactMaterial(new CANNON.ContactMaterial(brickMat, groundMat, { friction: 0.85, restitution: 0.18 }));
world.addContactMaterial(new CANNON.ContactMaterial(brickMat, brickMat, { friction: 0.72, restitution: 0.18 }));
world.addContactMaterial(new CANNON.ContactMaterial(carMat, brickMat, { friction: 0.5, restitution: 0.15 }));
world.addContactMaterial(new CANNON.ContactMaterial(carMat, groundMat, { friction: 0.85, restitution: 0.1 }));

const groundBody = new CANNON.Body({ mass: 0, material: groundMat });
groundBody.addShape(new CANNON.Plane());
groundBody.quaternion.setFromAxisAngle(new CANNON.Vec3(1, 0, 0), -Math.PI / 2);
world.addBody(groundBody);

const bw = 0.5, bh = 0.24, bd = 0.2;
const bricks = [];
for (let r = 0; r < 8; r++) {
  const y = bh / 2 + r * bh;
  for (let c = 0; c < 12; c++) {
    const offsetX = (r % 2 === 1) ? (bw * 0.25) : 0;
    const x = (c - 5.5) * bw + offsetX;
    for (let l = 0; l < 2; l++) {
      const z = (l - 0.5) * bd;
      const b = new CANNON.Body({
        mass: 2.5,
        material: brickMat,
        shape: new CANNON.Box(new CANNON.Vec3(bw/2 - 0.001, bh/2 - 0.001, bd/2 - 0.001)),
        position: new CANNON.Vec3(x, y, 20 + z) // Wall at Z = 20
      });
      world.addBody(b);
      bricks.push(b);
    }
  }
}

// Car moving in +Z direction towards wall at 20m
const carBody = new CANNON.Body({
  mass: 1250,
  material: carMat,
  shape: new CANNON.Box(new CANNON.Vec3(1.8/2, 1.45/2, 4.2/2)),
  position: new CANNON.Vec3(0, 1.45/2 + 0.1, 15), // 5m away
  velocity: new CANNON.Vec3(0, 0, 22) // 22 m/s
});
world.addBody(carBody);

console.log('Starting sim...');
for (let step = 0; step < 120; step++) {
  world.step(1/60);
}
console.log('Car pos Z:', carBody.position.z.toFixed(2), 'velocity Z:', carBody.velocity.z.toFixed(2));
let displaced = 0;
for (const b of bricks) {
  if (b.position.z > 21 || b.velocity.length() > 1) displaced++;
}
console.log('Bricks displaced:', displaced, '/', bricks.length);
"

