for (let r = 0; r < 8; r++) {
  const y = bh / 2 + r * (bh + 0.001);
  for (let c = 0; c < 12; c++) {
    const offsetZ = (r % 2 === 1) ? (bw * 0.25) : 0;
    const z = (c - 5.5) * (bw + 0.001) + offsetZ;
    for (let l = 0; l < 2; l++) {
      const x = 12 + (l - 0.5) * (bd + 0.001);
      const b = new CANNON.Body({
        mass: 2.5,
        material: brickMat,
        shape: new CANNON.Box(new CANNON.Vec3(bd/2 - 0.002, bh/2 - 0.002, bw/2 - 0.002)),
        position: new CANNON.Vec3(x, y, z)
      });
      world.addBody(b);
      bricks.push(b);
    }
  }
}

// Assemble car parts
const parts = [];
const constraints = [];

function createPart(name, mass, halfExtents, relPos) {
  const b = new CANNON.Body({
    mass: mass,
    material: carMat,
    shape: new CANNON.Box(halfExtents),
    position: new CANNON.Vec3(relPos.x, relPos.y, relPos.z)
  });
  b.name = name;
  b.broken = false;
  world.addBody(b);
  parts.push(b);
  return b;
}

const cabin = createPart('cabin', 650, new CANNON.Vec3(1.1, 0.45, 0.85), new CANNON.Vec3(0, 0.65, 0));
const frontClip = createPart('frontClip', 250, new CANNON.Vec3(0.65, 0.35, 0.8), new CANNON.Vec3(1.6, 0.55, 0));
const hood = createPart('hood', 35, new CANNON.Vec3(0.65, 0.04, 0.75), new CANNON.Vec3(1.6, 0.95, 0));
const fBumper = createPart('frontBumper', 25, new CANNON.Vec3(0.12, 0.15, 0.88), new CANNON.Vec3(2.35, 0.45, 0));
const rBumper = createPart('rearBumper', 20, new CANNON.Vec3(0.12, 0.15, 0.88), new CANNON.Vec3(-1.2, 0.45, 0));

function addBreakableConstraint(bodyA, bodyB, threshold, onBreak) {
  const c = new CANNON.LockConstraint(bodyA, bodyB);
  world.addConstraint(c);
  constraints.push({ c, bodyA, bodyB, threshold, onBreak, broken: false });
}

addBreakableConstraint(cabin, frontClip, 2500, () => console.log('Front clip crumple/detached!'));
addBreakableConstraint(frontClip, hood, 300, () => console.log('Hood flew off!'));
addBreakableConstraint(frontClip, fBumper, 150, () => console.log('Front bumper detached!'));
addBreakableConstraint(cabin, rBumper, 400, () => console.log('Rear bumper detached!'));

// Collision handlers
for (const p of parts) {
  p.addEventListener('collide', (e) => {
    const relV = Math.abs(e.contact.getImpactVelocityAlongNormal());
    const other = e.contact.bi === p ? e.contact.bj : e.contact.bi;
    const impulse = relV * Math.min(p.mass, other.mass || 1000);
    for (const item of constraints) {
      if (!item.broken && (item.bodyA === p || item.bodyB === p)) {
        if (impulse > item.threshold) {
          item.broken = true;
          world.removeConstraint(item.c);
          item.onBreak && item.onBreak();
        }
      }
    }
  });
}

// Set initial velocity to 22 m/s along +X
for (const p of parts) {
  p.position.x += 8.0; // Start at X = 8, wall is at 12
  p.velocity.set(22, 0, 0);
}

console.log('Simulating impact...');
for (let step = 0; step < 180; step++) {
  world.step(1/60);
}
console.log('Simulation complete! Cabin final X:', cabin.position.x.toFixed(2), 'velX:', cabin.velocity.x.toFixed(2));
let brokenCount = constraints.filter(c => c.broken).length;
console.log('Broken constraints:', brokenCount, '/', constraints.length);
"

